import java.util.*;
class Box { int quantity = 1; }

public class Main {
    public static void main(String[] args) {
        Box item = new Box();
        List<Box> original = new ArrayList<>();
        original.add(item);
        // 이 줄이 지금 수량을 남기는 스냅샷을 만들도록 고치세요.
        List<Box> snapshot = List.copyOf(original);
        // 스냅샷을 만든 뒤 원래 객체와 목록을 바꿔요.
        item.quantity = 2;
        original.add(new Box());
        System.out.println(snapshot.get(0).quantity);
        System.out.println(snapshot.size());
    }
}

